import{_ as e,o,c as s,a2 as n}from"./chunks/framework.D21_4UK8.js";const g=JSON.parse('{"title":"🔊 不滅のトーン・キング：Electro-Voice EVM-12L の伝説","description":"","frontmatter":{},"headers":[],"relativePath":"ja/electro-voice-evm12l.md","filePath":"ja/electro-voice-evm12l.md"}'),t={name:"ja/electro-voice-evm12l.md"};function r(l,a,i,p,c,d){return o(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="🔊-不滅のトーン・キング-electro-voice-evm-12l-の伝説" tabindex="-1">🔊 不滅のトーン・キング：Electro-Voice EVM-12L の伝説 <a class="header-anchor" href="#🔊-不滅のトーン・キング-electro-voice-evm-12l-の伝説" aria-label="Permalink to &quot;🔊 不滅のトーン・キング：Electro-Voice EVM-12L の伝説&quot;">​</a></h1><h3 id="キース・リチャーズ、スティーヴィー・レイ・ヴォーン、そしてロック史を決定づけた300wスピーカーの歴史。" tabindex="-1">キース・リチャーズ、スティーヴィー・レイ・ヴォーン、そしてロック史を決定づけた300Wスピーカーの歴史。 <a class="header-anchor" href="#キース・リチャーズ、スティーヴィー・レイ・ヴォーン、そしてロック史を決定づけた300wスピーカーの歴史。" aria-label="Permalink to &quot;キース・リチャーズ、スティーヴィー・レイ・ヴォーン、そしてロック史を決定づけた300Wスピーカーの歴史。&quot;">​</a></h3><p><strong>スタジオ・ジャーナル · トーン・ヒストリー | Main St Audio Labs</strong></p><hr><h2 id="⚡-1-ブリティッシュ・スピーカーへのアンチテーゼ" tabindex="-1">⚡ 1. ブリティッシュ・スピーカーへのアンチテーゼ <a class="header-anchor" href="#⚡-1-ブリティッシュ・スピーカーへのアンチテーゼ" aria-label="Permalink to &quot;⚡ 1. ブリティッシュ・スピーカーへのアンチテーゼ&quot;">​</a></h2><p>1960年代後半から1970年代にかけて、ロックギターのトーンは「ペーパーコーンの歪み（Speaker Breakup）」を前提としていました。伝統的な25W〜30Wの薄型ペーパーコーンは、大音量でたわんで歪むように設計されており、高域に粗いサチュレーションを生み出し、低域を圧縮していました。</p><p>しかし、ギタリストたちがよりハイゲインなプリアンプと大出力のクリーン・ヘッドルームを求め始めると、スタジオやステージで悲劇が起きました：<strong>従来のスピーカーが次々と焼き切れ、ボイスコイルが溶け、オープンコードが濁った音の塊と化してしまったのです。</strong></p><p>米国ミシガン州ブキャナンの <strong>Electro-Voice（EV）</strong> は、これとは正反対の音響的解決策を打ち出しました：<strong>「300Wの連続入力に耐え、コーン紙の歪みを完全排除した不滅のギタースピーカーを作る」</strong>。</p><p>こうして誕生したのが、伝説の <strong>Electro-Voice EVM-12L</strong> です。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                   伝統的コーン (25W-30W)           ELECTRO-VOICE EVM-12L (200W-300W)</span></span>
<span class="line"><span>                   ──────────────────────────       ─────────────────────────────────</span></span>
<span class="line"><span>  動作特性:        歪み、圧縮、飽和する。           線形、無限のヘッドルーム、コーン歪みゼロ。</span></span>
<span class="line"><span>  マグネット:      小型 (1.5〜2.5 kg)。             巨大セラミック (7.5 kg / 16 lbs)。</span></span>
<span class="line"><span>  フレーム:        薄いスチールプレス板。           肉厚アルミダイキャスト・フレーム。</span></span>
<span class="line"><span>  ボイスコイル:    1.5インチ 丸線。                 2.5インチ エッジワウンド・アルミ平角線。</span></span>
<span class="line"><span>  出力音圧レベル:  ~96〜97 dB SPL。                 100 dB SPL (爆発的・即座の音圧)。</span></span></code></pre></div><hr><h2 id="🔬-2-音響の重戦車-その驚異的な構造" tabindex="-1">🔬 2. 音響の重戦車：その驚異的な構造 <a class="header-anchor" href="#🔬-2-音響の重戦車-その驚異的な構造" aria-label="Permalink to &quot;🔬 2. 音響の重戦車：その驚異的な構造&quot;">​</a></h2><ol><li><strong>肉厚アルミダイキャスト・フレーム:</strong> プレス鋼板のようにネジ締めによる歪みが発生せず、強固な剛性を保持。</li><li><strong>2.5インチ・エッジワウンド・アルミボイスコイル:</strong> 平角線を隙間なく巻き上げることで磁束密度を最大化し、大電力による発熱を効率よく放熱。</li><li><strong>7.5 kgの超大型セラミックマグネット:</strong> コーン紙を電磁気力で完全に制動し、ピッキング瞬時の<strong>電光石火のトランジェント・スピード</strong>を実現。</li><li><strong>100 dB SPL @ 1W/1m の高能率:</strong> 50Wのアンプを繋いでも100Wアンプに匹敵する圧倒的な音圧を放出。</li></ol><hr><h2 id="🎸-3-トーン・マスターたちとevm-12l" tabindex="-1">🎸 3. トーン・マスターたちとEVM-12L <a class="header-anchor" href="#🎸-3-トーン・マスターたちとevm-12l" aria-label="Permalink to &quot;🎸 3. トーン・マスターたちとEVM-12L&quot;">​</a></h2><ul><li><strong>👅 キース・リチャーズ＆ローリング・ストーンズ（1978–1981）：</strong> 『<em>Some Girls</em>』『<em>Tattoo You</em>』期において、5弦オープンGチューニングの1本1本の弦の分離感と、6L6管のバイト感を余すところなく鳴らし切るため、無垢材コンボにEVM-12Lを搭載。</li><li><strong>⚡ スティーヴィー・レイ・ヴォーン：</strong> Dumble Steel String Singer やカスタムFenderコンボにEVM-12Lを採用。.013ゲージの強烈なピッキングでも低域が潰れず、太くクリアなテキサス・トーンを確立。</li><li><strong>🥊 ザック・ワイルド：</strong> ピッキング・ハーモニクスと重低音ミュートに耐えうるスピーカーとして愛用。後にシグネチャーモデル <em>EVM-12L Black Label</em> も誕生。</li><li><strong>🎩 ジョー・ボナマッサ＆エリック・ジョンソン：</strong> ネック全域で均一に倍音が伸びるヴァイオリン・トーンの心臓部として信頼。</li></ul><hr><h2 id="🌲-4-無垢材-hardwood-とバスレフポートの黄金比" tabindex="-1">🌲 4. 無垢材（Hardwood）とバスレフポートの黄金比 <a class="header-anchor" href="#🌲-4-無垢材-hardwood-とバスレフポートの黄金比" aria-label="Permalink to &quot;🌲 4. 無垢材（Hardwood）とバスレフポートの黄金比&quot;">​</a></h2><p>EVM-12Lを薄い合板のオープンバックキャビネットに載せるのは、そのポテンシャルの半分を捨てるようなものです。</p><p><strong>高密度な無垢材（マホガニー、ブビンガ、オーク等）</strong> と <strong>前面チューニング・バスレフポート</strong> を組み合わせることで、1x12のコンパクトなサイズでありながら、4x12スタックアンプに匹敵するタイトで圧倒的な重低音パンチが完成します。</p><hr><p>👉 <a href="/ja/audio-mics-guide.html"><strong>EVM-12Lの24テイクの使い分けを学ぶ：キャビネット＆マイク完全ガイド →</strong></a></p>`,22)])])}const m=e(t,[["render",r]]);export{g as __pageData,m as default};
